fn repairCandidates(_: u16) []const u16 {
    return &.{};
}

fn repairClass(_: u16) RepairClass {
    return .none;
}

fn ruleSideLabels(rule: u16) []const SideLabel {
    _ = rule;
    return &.{};
}

